/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_append">append</param>
void  create(boolean _append)
{
    boolean append = _append;
    append = true;

    if(element.salesQuotationLine.ItemId == ''
        && element.salesQuotationLine.LineNum)
    {
        throw error("@NDX:NXAItemId");
    }

    next create(append);

    FormRun         formRun = this.formRun();
    formRun.design(0).controlName('SalesQuotationLine_KCS_QLLVPosition').setFocus();

}

/// <summary>
/// designed from AVA
/// </summary>
void  delete()
{
    boolean         selectedOnlyOne = false;
    SalesQuotationLine      locSalesQuotationLine; 
    SalesQuotationLine      spanGrpSalesQuotationLine;
    SalesQuotationLine      salesQuotationLineLVGroup;

    selectedOnlyOne = MultiselectionHelper::AVAOnlyOneRecordSelected(this);
    locSalesQuotationLine.data(this.cursor());

    next delete();

    if (selectedOnlyOne)
    {
        if (locSalesQuotationLine.KCS_QLInternalPosition != 0)
        {
            select count(RecId) from  salesQuotationLineLVGroup 
                where  salesQuotationLineLVGroup.QuotationId == locSalesQuotationLine.QuotationId
                &&  salesQuotationLineLVGroup.KCS_QLLVPosition == locSalesQuotationLine.KCS_QLLVPosition;

            if (salesQuotationLineLVGroup.RecId > 1)
            {
                if (Box::yesNo("@NDX:NXAMustSpanGrpBeDelete",DialogButton::Yes) == DialogButton::Yes)
                {
                    delete_from spanGrpSalesQuotationLine
                    where spanGrpSalesQuotationLine.QuotationId == locSalesQuotationLine.QuotationId
                    && spanGrpSalesQuotationLine.KCS_QLLVPosition == locSalesQuotationLine.KCS_QLLVPosition;
                }
            }
        }
        this.markDoubleItem(locSalesQuotationLine);
    }

    SysGlobalCache globalCache = ClassFactory.globalCache();
    globalCache.clear(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)));

}

/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    next init();
    FormDataSource          salesQuotationLineDS =    this;

    salesQuotationLineDS.object(fieldNum(SalesQuotationLine, ItemId)).mandatory(true);
    salesQuotationLineDS.object(fieldNum(SalesQuotationLine,LineAmount)).allowEdit(false);

    boolean isCalledFromLP = TradeFormHelper::isCalledFromForm(this.formRun().args(), formStr(SalesQuotationListPage));

    if(isCalledFromLP )
    {
        SalesQuotationTable          callerRecord = this.formRun().args().record();
        SysQuery::findOrCreateRange(this.query().dataSourceTable(tableNum(SalesQuotationLine)),fieldNum(SalesQuotationLine,QuotationId)).value(callerRecord.QuotationId);
    }
}

/// <summary>
/// designed from AVA
/// </summary>
public void deleteMarked()
{
    SalesQuotationLine      locSalesQuotationLine; 
    boolean                 onlyOneRecordMarked = MultiselectionHelper::AVAOnlyOneRecordMarked(this);
    SalesQuotationLine      spanGrpSalesQuotationLine;
    SalesQuotationLine      salesQuotationLineLVGroup;

    locSalesQuotationLine.data(this.cursor());

    select count(RecId) from  salesQuotationLineLVGroup
                where  salesQuotationLineLVGroup.QuotationId == locSalesQuotationLine.QuotationId
                &&  salesQuotationLineLVGroup.KCS_QLLVPosition == locSalesQuotationLine.KCS_QLLVPosition;

    next deleteMarked();

    if (onlyOneRecordMarked)
    {
        if (locSalesQuotationLine.KCS_QLInternalPosition != 0)
        {
            if (salesQuotationLineLVGroup.RecId > 1)
            {
                if (Box::yesNo("@NDX:NXAMustSpanGrpBeDelete",DialogButton::Yes) == DialogButton::Yes)
                {
                    delete_from spanGrpSalesQuotationLine
                    where spanGrpSalesQuotationLine.QuotationId == locSalesQuotationLine.QuotationId
                    && spanGrpSalesQuotationLine.KCS_QLLVPosition == locSalesQuotationLine.KCS_QLLVPosition;
                }
            }
        }
    }
    this.markDoubleItem(locSalesQuotationLine);

    SysGlobalCache globalCache = ClassFactory.globalCache();
    globalCache.clear(strFmt("@NDX:NXAP1P2",curUserId(),classStr(SalesQuotationLineType)));
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_selectedRecord">_selectedRecord</param>
/// <param name = "_refreshDS">_refreshDS</param>
public void markDoubleItem(SalesQuotationLine   _selectedRecord, boolean    _refreshDS = true)
{
    SalesQuotationLine      nextSalesQuotationLine;

    if (_refreshDS)
    {
        select firstonly nextSalesQuotationLine
            order by LineNum
        where nextSalesQuotationLine.QuotationId == _selectedRecord.QuotationId
        && nextSalesQuotationLine.LineNum >= _selectedRecord.LineNum;

        if (!nextSalesQuotationLine)
        {
            select firstonly nextSalesQuotationLine
                order by LineNum desc
                where nextSalesQuotationLine.QuotationId == _selectedRecord.QuotationId
                && nextSalesQuotationLine.LineNum <= _selectedRecord.LineNum;
        }
    }
    SalesQuotationLine          avaSalesQuotationLineLoc;
    SalesQuotationLine          salesQuotationLineItemGrp;

    select count(RecId) from salesQuotationLineItemGrp
        where salesQuotationLineItemGrp.ItemId == _selectedRecord.ItemId
        && salesQuotationLineItemGrp.QuotationId == _selectedRecord.QuotationId;

    if (salesQuotationLineItemGrp.RecId == 1)
    {
        while select count(RecId) from  salesQuotationLineItemGrp
            group by ItemId
            where salesQuotationLineItemGrp.QuotationId == _selectedRecord.QuotationId
        {
            if (salesQuotationLineItemGrp.RecId == 1)
            {
                ttsbegin;
                update_recordset avaSalesQuotationLineLoc
                    setting KCS_MultipleItem = ''
                    where avaSalesQuotationLineLoc.ItemId == salesQuotationLineItemGrp.itemId
                    //&& avaSalesQuotationLineLoc.QuotationId == this.quotationId;
                    && avasalesquotationlineloc.QuotationId == _selectedRecord.QuotationId;
                ttscommit;
            }
        }
    }


    if (_refreshDS)
    {
        this.executeQuery();
        this.positionToRecord(nextSalesQuotationLine);
    }

}
